/* Shashka Game - Game Logic Controller */

'use strict';

class GameController {
  constructor() {
    this.board = null;
    this.gameId = null;
    this.state = null;
    this.myColor = 'white';     // white = player1, black = player2
    this.selectedSquare = null;
    this.timerInterval = null;
    this.myTime = 0;
    this.oppTime = 0;
    this.moveHistory = [];
  }

  /* Initialize a game on the game page */
  init(gameId) {
    this.gameId = gameId;
    this.board = new window.Board('gameBoard');
    this.board.onSquareClick = (row, col) => this.handleSquareClick(row, col);
    this.loadGame();
  }

  async loadGame() {
    try {
      const state = await window.App.api.get('/game/' + this.gameId);
      this.applyState(state);
    } catch (e) {
      window.App.toast('O\'yinni yuklab bo\'lmadi', 'error');
    }
  }

  applyState(state) {
    this.state = state;
    this.board.setBoard(state.board);

    // Determine my color
    if (window.App.user && state.player2_id === window.App.user.id) {
      this.myColor = 'black';
      this.board.setFlipped(true);
    }

    this.myTime = this.myColor === 'white' ? state.player1_time : state.player2_time;
    this.oppTime = this.myColor === 'white' ? state.player2_time : state.player1_time;
    this.moveHistory = state.moves || [];

    this.renderHistory();
    this.updateTurnIndicator();
    this.startTimer();

    if (state.status === 'finished') {
      this.showResult(state.result);
    }
  }

  /* ----- Square interaction ----- */
  handleSquareClick(row, col) {
    if (!this.state || this.state.status !== 'active') return;
    if (this.state.current_turn !== this.myColor) {
      window.App.toast('Sizning navbatingiz emas', 'info');
      return;
    }

    const piece = this.state.board[row][col];

    if (this.selectedSquare) {
      // Try to move
      const from = this.coordsToSquare(this.selectedSquare.row, this.selectedSquare.col);
      const to = this.coordsToSquare(row, col);

      if (this.selectedSquare.row === row && this.selectedSquare.col === col) {
        // Deselect
        this.selectedSquare = null;
        this.board.clearSelection();
        return;
      }

      this.makeMove(from, to);
      this.selectedSquare = null;
      this.board.clearSelection();
    } else {
      // Select a piece if it's mine
      if (this.isMyPiece(piece)) {
        this.selectedSquare = { row, col };
        const moves = this.computeValidMoves(row, col, piece);
        this.board.select(row, col, moves);
        window.App.sound.play('tap');
      }
    }
  }

  isMyPiece(piece) {
    if (piece === 0) return false;
    const whitePieces = [2, 4];
    const blackPieces = [1, 3];
    return this.myColor === 'white' ? whitePieces.includes(piece) : blackPieces.includes(piece);
  }

  /* Client-side valid move hint (server is authoritative) */
  computeValidMoves(row, col, piece) {
    const moves = [];
    const isKing = (piece === 3 || piece === 4);
    const isWhite = (piece === 2 || piece === 4);
    const dirs = isKing
      ? [[-1, -1], [-1, 1], [1, -1], [1, 1]]
      : (isWhite ? [[-1, -1], [-1, 1]] : [[1, -1], [1, 1]]);

    dirs.forEach((d) => {
      const nr = row + d[0], nc = col + d[1];
      if (this.inBounds(nr, nc) && this.state.board[nr][nc] === 0) {
        moves.push({ row: nr, col: nc });
      }
      // Capture
      const cr = row + d[0] * 2, cc = col + d[1] * 2;
      const mr = row + d[0], mc = col + d[1];
      if (this.inBounds(cr, cc) && this.state.board[cr][cc] === 0
          && this.inBounds(mr, mc) && this.isOpponentPiece(this.state.board[mr][mc], isWhite)) {
        moves.push({ row: cr, col: cc });
      }
    });
    return moves;
  }

  isOpponentPiece(piece, iAmWhite) {
    if (piece === 0) return false;
    const whitePieces = [2, 4];
    return iAmWhite ? !whitePieces.includes(piece) : whitePieces.includes(piece);
  }

  inBounds(r, c) { return r >= 0 && r < 8 && c >= 0 && c < 8; }

  /* ----- Make a move ----- */
  async makeMove(from, to) {
    try {
      const result = await window.App.api.post('/game/move', {
        game_id: this.gameId, from: from, to: to
      });

      window.App.sound.play(result.capturedPieces && result.capturedPieces.length ? 'capture' : 'move');

      this.state.board = result.newBoard;
      this.state.current_turn = result.currentTurn;
      this.board.setBoard(result.newBoard);
      this.updateTurnIndicator();

      // Notify opponent via websocket
      window.App.wsSend({ type: 'game_move', game_id: this.gameId, from: from, to: to });

      if (result.gameEnded) {
        this.showResult(result.result);
      }
    } catch (e) {
      window.App.toast(e.message, 'error');
    }
  }

  /* Called when opponent moves (via WebSocket) */
  onOpponentMove(msg) {
    if (msg.game_id !== this.gameId) return;
    this.loadGame();
    window.App.sound.play('move');
  }

  /* ----- Timer ----- */
  startTimer() {
    this.stopTimer();
    this.timerInterval = setInterval(() => {
      if (this.state.status !== 'active') {
        this.stopTimer();
        return;
      }
      if (this.state.current_turn === this.myColor) {
        this.myTime = Math.max(0, this.myTime - 1);
      } else {
        this.oppTime = Math.max(0, this.oppTime - 1);
      }
      this.renderTimers();
    }, 1000);
  }

  stopTimer() {
    if (this.timerInterval) {
      clearInterval(this.timerInterval);
      this.timerInterval = null;
    }
  }

  renderTimers() {
    const myEl = document.getElementById('myTimer');
    const oppEl = document.getElementById('oppTimer');
    if (myEl) {
      myEl.textContent = this.formatTime(this.myTime);
      myEl.className = 'timer' + (this.state.current_turn === this.myColor ? ' active' : '') + (this.myTime < 30 ? ' low' : '');
    }
    if (oppEl) {
      oppEl.textContent = this.formatTime(this.oppTime);
      oppEl.className = 'timer' + (this.state.current_turn !== this.myColor ? ' active' : '');
    }
  }

  formatTime(sec) {
    const m = Math.floor(sec / 60);
    const s = sec % 60;
    return m + ':' + (s < 10 ? '0' : '') + s;
  }

  updateTurnIndicator() {
    const el = document.getElementById('turnIndicator');
    if (el) {
      el.textContent = this.state.current_turn === this.myColor ? 'Sizning navbatingiz' : 'Raqib o\'ylayapti...';
    }
    this.renderTimers();
  }

  /* ----- Move history ----- */
  renderHistory() {
    const el = document.getElementById('moveHistory');
    if (!el) return;
    el.innerHTML = this.moveHistory.map((m, i) =>
      '<div class="move-row"><span>' + (i + 1) + '.</span> <span>' + (m.move_notation || (m.from_square + '-' + m.to_square)) + '</span></div>'
    ).join('');
  }

  /* ----- Actions ----- */
  async resign() {
    if (!confirm('Taslim bo\'lishni xohlaysizmi?')) return;
    try {
      await window.App.api.post('/game/' + this.gameId + '/resign', {});
      this.showResult(this.myColor === 'white' ? 'black_wins' : 'white_wins');
    } catch (e) {
      window.App.toast(e.message, 'error');
    }
  }

  async offerDraw() {
    try {
      await window.App.api.post('/game/' + this.gameId + '/draw', { action: 'offer' });
      window.App.toast('Durang taklif qilindi', 'info');
    } catch (e) {
      window.App.toast(e.message, 'error');
    }
  }

  /* ----- Result overlay ----- */
  showResult(result) {
    this.stopTimer();
    let won = false, draw = false;
    if (result === 'draw') {
      draw = true;
    } else {
      const iWonAs = this.myColor === 'white' ? 'black_wins' : 'white_wins';
      // In this engine: black_wins => player1(white) wins. Map by winner instead:
      won = (this.state.winner_id && window.App.user && this.state.winner_id === window.App.user.id);
    }

    const emoji = draw ? '🤝' : (won ? '🏆' : '😔');
    const title = draw ? 'Durang!' : (won ? 'G\'alaba!' : 'Mag\'lubiyat');
    window.App.sound.play(won ? 'win' : (draw ? 'tap' : 'lose'));

    let overlay = document.querySelector('.result-overlay');
    if (!overlay) {
      overlay = document.createElement('div');
      overlay.className = 'result-overlay';
      overlay.innerHTML = '<div class="result-card"></div>';
      document.body.appendChild(overlay);
    }
    overlay.querySelector('.result-card').innerHTML =
      '<div class="result-emoji">' + emoji + '</div>' +
      '<h2>' + title + '</h2>' +
      '<button class="btn btn-grad mt-16" onclick="window.App.navigate(\'home\')">Bosh sahifa</button>';
    requestAnimationFrame(() => overlay.classList.add('show'));
  }

  coordsToSquare(row, col) {
    return String.fromCharCode(97 + col) + (8 - row);
  }
}

window.Game = new GameController();
